export async function deliver(job: DeliveryJob) {
  const attempt = (attempts.get(job.endpointId) ?? 0) + 1
  attempts.set(job.endpointId, attempt)
  const response = await fetch(job.url, requestFor(job))
  if (!response.ok) await queue.retry(job, backoff(attempt))
}

export function currentPeriod(account: Account, now = new Date()): Period {
  const anchor = account.billingAnchorDay
  const start = startOfPeriod(anchor, now)
  return { start, end: addMonths(start, 1) }
}

