{"file_path": "/home/demo/web-dashboard/src/db/queries/dailyUsage.ts", "content": "export async function dailyUsage(db: Db, accountId: string, opts: { periods: number }) {
  return db.select({ day: sql`date_trunc('day', ${usageRollups.hour})`, requests: sum(usageRollups.requests) })
    .from(usageRollups)
    .where(and(eq(usageRollups.accountId, accountId), gte(usageRollups.hour, periodsAgo(opts.periods))))
    .groupBy(sql`1`).orderBy(sql`1`)
}
"}

